<template>
  <view 
    class="camera-upload" 
    :style="{
      width: width,
      height: height,
      backgroundColor: backgroundColor,
      borderRadius: borderRadius
    }"
    @click="handleClick"
  >
    <view class="camera-icon">
      <slot>
        <uni-icons type="camera" :size="iconSize" :color="iconColor" />
      </slot>
    </view>
  </view>
</template>

<script setup>
import { defineProps, defineEmits } from 'vue'

const props = defineProps({
  // 宽度，默认 168rpx
  width: {
    type: String,
    default: '168rpx'
  },
  // 高度，默认 168rpx
  height: {
    type: String,
    default: '168rpx'
  },
  // 背景颜色，默认 #D9D9D9
  backgroundColor: {
    type: String,
    default: '#D9D9D9'
  },
  // 图标大小，默认 32
  iconSize: {
    type: [Number, String],
    default: 32
  },
  // 图标颜色，默认 #999
  iconColor: {
    type: String,
    default: '#999'
  },
  // 圆角，默认 16px
  borderRadius: {
    type: String,
    default: '16px'
  }
})

const emit = defineEmits(['click'])

const handleClick = () => {
  emit('click')
}
</script>

<style scoped>
.camera-upload {
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
  box-sizing: border-box;
}

.camera-icon {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100%;
}
</style>